def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    capacity = supply / float(WATER_REQ)
    scarcity = 0
    if capacity <= 1.05:
        scarcity = 2
    elif capacity <= 2.05:
        scarcity = 1

    prev_bids = []
    threat_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = 0.0
        if prev and prev.get('bid') is not None:
            pbid = float(prev.get('bid', 0.0))
            prev_bids.append(pbid)
        opp_hp = opp.get('hp', 10)
        opp_nwd = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0.0)
        if opp_hp <= 4 or opp_nwd >= 1:
            desperate_count += 1
            threat_bids.append(max(pbid, DAILY_SALARY * 0.9))
        else:
            threat_bids.append(pbid)
        if opp_budget >= 180 and pbid >= 80:
            rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else 0.0

    urgency = 0
    if hp <= 3:
        urgency += 2
    elif hp <= 5:
        urgency += 1
    if no_water_days >= 1:
        urgency += 2

    if urgency >= 3:
        target = max(95.0, highest_threat + 6.0)
        if scarcity == 2:
            target = max(target, 125.0)
        elif scarcity == 1:
            target = max(target, 105.0)
    elif urgency >= 1:
        if scarcity == 2:
            target = max(62.0, highest_prev + 3.0)
        elif scarcity == 1:
            target = max(42.0, highest_prev * 0.55 + 4.0)
        else:
            target = max(24.0, highest_prev * 0.22 + 2.0)
    else:
        if scarcity == 2:
            target = max(36.0, min(72.0, highest_prev * 0.35 + 3.0))
        elif scarcity == 1:
            target = max(18.0, min(40.0, highest_prev * 0.18 + 2.0))
        else:
            target = 8.0

    if rich_aggressive >= 2 and urgency == 0:
        target = min(target, 16.0)
    if desperate_count >= 2 and urgency >= 1:
        target = max(target, highest_threat + 8.0)

    if day >= 8:
        target *= 1.12
    elif day <= 2 and urgency == 0:
        target *= 0.85

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 20.0
    elif hp > 2:
        reserve = 8.0

    affordable = max(0.0, budget - reserve)
    bid = min(target, affordable if affordable > 0 else budget)

    if urgency >= 3 and budget > 0:
        bid = min(max(bid, min(budget, 110.0)), budget)

    if bid < 0:
        bid = 0.0
    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Determine how many water units are effectively available this day
    # (We only need 1 unit of WATER_REQ; higher supply just affects competition.)
    effective_units = int(max(0, supply // float(WATER_REQ)))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        # No competition: spend to secure survival quickly
        if hp <= 2 or no_water_days >= 1:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.55)

    # Read yesterday's bids from previous_trace for immediate reaction
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If someone was bidding extremely high yesterday, they likely expect to win water again.
    # We bid just below that pressure to reduce cost while still outbidding typical mid bids.
    # Thresholds tuned to observed meta-round bids (~185-243).
    if highest_prev_bid >= 235:
        target = DAILY_SALARY * 0.75  # 67.5
        # If we are in danger, increase aggressiveness.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        elif hp <= 4 or no_water_days >= 1:
            target = DAILY_SALARY * 0.85
        # Also ensure we are not trivially low when supply is tight.
        if effective_units <= 1:
            target = max(target, DAILY_SALARY * 0.65)
    elif highest_prev_bid >= 190:
        target = DAILY_SALARY * 0.65
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.9
        elif hp <= 4 or no_water_days >= 1:
            target = DAILY_SALARY * 0.8
        if effective_units <= 1:
            target = max(target, DAILY_SALARY * 0.6)
    else:
        # Lower prior pressure: bid moderately to conserve budget.
        target = DAILY_SALARY * 0.55
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.85
        elif hp <= 4 or no_water_days >= 1:
            target = DAILY_SALARY * 0.7

    # Convert target into a feasible bid given our budget.
    bid = min(budget, target)

    # If we still have budget and are very low HP, ensure we don't bid too little.
    if (hp <= 2 or no_water_days >= 2) and bid < DAILY_SALARY * 0.6:
        bid = min(budget, DAILY_SALARY * 0.85)

    # Final clamp: bid must be non-negative.
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(prev_bids)
    if supply < 18:
        return min(my_status['budget'], max_prev + 5.0)

    if max_prev > DAILY_SALARY * 1.1:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    return min(my_status['budget'], max(DAILY_SALARY * 0.5, max_prev * 0.95))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Look at previous_trace of all alive opponents
    yesterday_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine baseline based on supply
    if supply >= 20:
        baseline = DAILY_SALARY * 0.25
    else:
        baseline = DAILY_SALARY * 0.35

    # Adjust based on yesterday's highest bid
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # Cindy's bids are high; if she's alive, she might repeat
        if max_prev > DAILY_SALARY * 0.8:
            if hp > 3:
                # Conservative, let others fight
                bid = min(budget, DAILY_SALARY * 0.2)
            else:
                # Need water, bid moderately higher than second highest
                second_highest = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else max_prev * 0.5
                bid = min(budget, max(baseline, second_highest + 2))
        else:
            # Lower pressure, bid slightly above max
            bid = min(budget, max(baseline, max_prev + 1))
    else:
        # No history, use default
        if hp <= 2 or no_water >= 1:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.4)

    # Ensure bid is within reasonable bounds
    bid = max(0, bid)
    # Avoid overspending on last day? Not needed.
    return bid
